import pathlib,json,csv,hashlib
p=pathlib.Path(__file__).parent
result=json.loads((p/'results.json').read_text());rows=result['results']
assert len(rows)==5 and len({r['libraryId'] for r in rows})==5 and all('error' not in r for r in rows)
events=[json.loads(x) for x in (p/'events.jsonl').read_text().splitlines()];refs={}
for e in events:
 for ref in ([e['evidence']] if isinstance(e.get('evidence'),dict) else e.get('evidence',[])):refs[ref['path']]=ref
for path,ref in refs.items():assert hashlib.sha256((p/path).read_bytes()).hexdigest()==ref['sha256']
summary=[]
for r in rows:
 c=r['comparisons'];posts=[s for s in r['steps'] if s['method']=='POST'];states=[next(x['digest'] for x in s['hidden'] if x['field']=='__VIEWSTATE') for s in r['steps']]
 summary.append({'library':r['name'],'new_session_identifier_differs':c['independentSessionIdentifiersDiffer'],'identifier_stable_within_session':c['sameSessionIdentifierStable'],'viewstate_differs_on_every_observed_response':len(states)==len(set(states)),'initial_state_reuse_works':c['originalStateReuseRecognized'],'initial_vs_updated_state_same_history_results':c['originalVsResponseStateHistorySameResults'],'history_same_id_title_set':sorted((x['recordId'],x['title']) for x in posts[1]['records'])==sorted((x['recordId'],x['title']) for x in posts[2]['records']),'repeated_wings_same_results':c['repeatWingsSameResults'],'recognized_searches':sum(s['recognizedSearch'] for s in posts),'wings_records':posts[0]['returned'],'history_records':posts[1]['returned'],'history_total':posts[1]['total']})
with (p/'comparison.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(summary[0]));w.writeheader();w.writerows(summary)
report=['# e-Granthalaya session and form-state reuse — 8 November 2026','','Five libraries in five clusters were tested using fresh sessions, repeated page loads and four successive searches per library. No item-detail requests were made.','','## Results','','| Library | New-session ID differs | Same-session ID stable | Original-state reuse | Wings of Fire rows | History rows (total) |','|---|---|---|---|---:|---:|']
for r in summary:report.append(f"| {r['library']} | {r['new_session_identifier_differs']} | {r['identifier_stable_within_session']} | {r['initial_state_reuse_works']} | {r['wings_records']} | {r['history_records']} ({r['history_total']}) |")
report+=['','For every library, the __VIEWSTATE bytes differed on every observed response, including repeated GETs in the same session and repeated identical queries. Most other hidden field values stayed the same on fresh/repeated form loads; search responses additionally carry result-specific hidden fields. Session identifiers differed across independent fresh sessions but stayed stable during that session’s requests.','','All 20 search POSTs were recognized scoped searches. Reusing the original form state for a second query worked in all five libraries. Repeating that query using state from the previous results produced the same set of native IDs/titles and total in every case. Four libraries also preserved exact order; Ratna-Sagar reordered records with identical titles (native IDs 90573/90559 and 61481/61480/49269) while keeping the same first-page record set and total 557. No cause for the tie ordering is assumed. Returning to Wings of Fire using updated state reproduced its first result set.','','Therefore changing state bytes do not establish that a new initial-form GET is required before every search. The tested short same-library sessions supported one setup GET followed by repeated search POSTs. A search response itself supplies updated form state. This experiment does not establish arbitrary fixed constants, cross-library or cross-cluster state reuse, session lifetime, restart persistence, concurrent sharing or a no-cookie method. No production/audit implementation or classification was changed.','','## Request sequence per library','','1. Fresh GET creates session A and original form state.','2. Independent fresh GET creates session B for byte/identifier comparison.','3. GET with A’s cookie tests changes within the same session.','4. POST Wings of Fire using A’s original form state.','5. POST History reusing A’s original form state.','6. POST History using the state returned by step 5.','7. POST Wings of Fire using the state returned by step 6.','','Total: 35 catalog requests (15 GET, 20 POST), plus one robots-policy request. Existing serial pacing, exclusive locks, allowed origins, access guards and bounded responses were retained. Main collector checkpointed before the test and resumes unchanged after archival. These checks do not add newly assessed library IDs.','','## Evidence','','`results.json` contains dated steps, comparisons, native IDs/titles, returned counts and evidence references; `comparison.csv` is the short table. `events.jsonl` and `bodies/` retain sanitized source evidence. Hidden form values and session identifiers were compared in memory; only SHA-256 fingerprints, lengths and equality results were saved. No reusable session cookie or hidden state is published. `test.mjs` is the executed one-off harness with its original workspace paths. `validation.json` records file/body hashes.']
assert all(all(r[k] for k in ['new_session_identifier_differs','identifier_stable_within_session','viewstate_differs_on_every_observed_response','initial_state_reuse_works','history_same_id_title_set','repeated_wings_same_results']) and r['recognized_searches']==4 for r in summary)
(p/'REPORT.md').write_text('\n'.join(report)+'\n')
(p/'validation.json').write_text(json.dumps({'valid':True,'libraries':5,'recognizedSearches':20,'validatedBodies':len(refs),'requests':sum(e['type']=='request_started' for e in events),'summary':summary,'fileHashes':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in p.iterdir() if f.is_file() and f.name!='validation.json'}},indent=2)+'\n')
print(json.dumps(summary,indent=2))
